package dev.jevmod.mind;

import dev.jevmod.JevMod;
import dev.jevmod.api.mind.MindContext;
import dev.jevmod.body.*;
import dev.jevmod.core.Json;
import com.google.gson.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.neoforged.neoforge.gametest.*;
import java.nio.file.*;
import java.util.*;

@GameTestHolder("jevmod") @PrefixGameTestTemplate(false)
public final class QolGameTests {
    @GameTest(template="empty",timeoutTicks=80) public static void editableFactoryScriptRebuildsAndAdaptsAfterDeath(GameTestHelper h){
        var core=core(h);var pos=core.getBlockPos().east(3);h.getLevel().setBlock(pos,BodyContent.BERCO.get().defaultBlockState(),3);h.getLevel().setBlock(pos.above(),BodyContent.BERCO.get().defaultBlockState().setValue(BercoBlock.HALF,DoubleBlockHalf.UPPER),3);core.bindPort("berco",pos);
        var example=JevMod.minds().catalog().systems.get("body_factory");var config=example.config().deepCopy();config.getAsJsonObject("spec").addProperty("duration_ticks",20);String id="qol_factory_test";JevMod.minds().catalog().systems.put(id,new SystemDef(id,example.engine(),example.script(),example.module(),example.apis(),1,config,example.rules(),true));core.useSystems(List.of(id));
        h.runAtTickTime(26,()->{h.assertTrue(core.error().isEmpty(),"Factory script must work: "+core.error());h.assertTrue(core.body() instanceof GeneratedBody,"Script must construct and bind a first body");var first=(GeneratedBody)core.body();h.assertTrue(first.spec().metadata().get("generation").getAsInt()==1,"Metadata must mark first generation");first.hurt(h.getLevel().damageSources().magic(),100);first.discard();});
        h.runAtTickTime(56,()->{h.assertTrue(core.error().isEmpty(),"Adaptation script must work: "+core.error());h.assertTrue(core.body() instanceof GeneratedBody,"Script must replace its dead body");var next=(GeneratedBody)core.body();h.assertTrue(next.isAlive()&&next.spec().metadata().get("generation").getAsInt()==2&&next.spec().resistances().contains("minecraft:magic"),"Second generation must adapt to recorded fatal damage");core.setEnabled(false);JevMod.minds().catalog().systems.remove(id);h.succeed();});
    }
    private static MindCoreEntity core(GameTestHelper h){var pos=h.absolutePos(new BlockPos(1,1,1));h.getLevel().setBlock(pos,MindContent.CORE.get().defaultBlockState(),3);var core=(MindCoreEntity)h.getLevel().getBlockEntity(pos);core.configure("jarvis");core.useSystems(List.of());return core;}
    private static MindContext context(MindCoreEntity core){return new MindContext(core,SystemDef.parse(new JsonObject(),"qol_test"));}
    private static GeneratedBody body(GameTestHelper h,MindCoreEntity core){var b=BodyContent.BODY.get().create(h.getLevel());b.moveTo(core.getBlockPos().getX()+2.5,core.getBlockPos().getY(),core.getBlockPos().getZ()+2.5,0,0);h.getLevel().addFreshEntity(b);core.bindBody(b.getUUID());return b;}
    private static JsonObject call(MindContext context,String operation,JsonObject args){try{return MindExtensions.call("jev:core",context,operation,args).getAsJsonObject();}catch(Exception e){throw new RuntimeException(e);}}
    @GameTest(template="empty",timeoutTicks=65) public static void rulesBuildReleaseAndBindBodyThroughBercoServices(GameTestHelper h){
        var core=core(h);var pos=core.getBlockPos().east(3);h.getLevel().setBlock(pos,BodyContent.BERCO.get().defaultBlockState(),3);h.getLevel().setBlock(pos.above(),BodyContent.BERCO.get().defaultBlockState().setValue(BercoBlock.HALF,DoubleBlockHalf.UPPER),3);var ctx=context(core);
        var coords=new JsonObject();coords.addProperty("x",pos.getX());coords.addProperty("y",pos.getY()+1);coords.addProperty("z",pos.getZ());var spec=BodySpec.parse(Json.parseObject("{\"duration_ticks\":20,\"resistances\":[\"lava\"],\"metadata\":{\"generation\":2}}"));coords.add("spec",spec.json());
        h.runAtTickTime(2,()->{call(ctx,"berco.begin",coords);h.assertTrue(call(ctx,"berco.status",coords).get("running").getAsBoolean(),"Mind must begin through upper-half coordinates");call(ctx,"berco.cancel",coords);h.assertTrue(!call(ctx,"berco.status",coords).get("running").getAsBoolean(),"Mind must cancel");var rules=new JsonObject();rules.addProperty("engine","rules");var entries=new JsonArray();var rule=new JsonObject();rule.add("when",new JsonObject());var actions=new JsonArray();var action=new JsonObject();action.addProperty("op","berco.begin");action.add("args",coords);actions.add(action);rule.add("actions",actions);entries.add(rule);rules.add("rules",entries);try{new RuleModule(SystemDef.parse(rules,"factory_test")).tick(ctx);}catch(Exception e){throw new RuntimeException(e);}});
        h.runAtTickTime(26,()->{h.assertTrue(call(ctx,"berco.status",coords).get("ready").getAsBoolean(),"Recipe must finish at configured game ticks");coords.addProperty("bind",true);var result=call(ctx,"berco.release",coords);h.assertTrue(result.get("released").getAsBoolean(),"Mind must release body");h.assertTrue(core.bodyId().toString().equals(result.get("body_id").getAsString()),"Release must return UUID and bind on request");h.assertTrue(((GeneratedBody)core.body()).spec().equals(spec),"Resistance/metadata must reach body");h.assertTrue(!call(ctx,"berco.release",coords).get("released").getAsBoolean(),"Second release must not duplicate body");h.succeed();});
    }
    @GameTest(template="empty",timeoutTicks=65) public static void bodyQueriesResistanceAndFatalDamageSurviveEntityRemoval(GameTestHelper h){
        var core=core(h);var b=body(h,core);b.setSpec(BodySpec.parse(Json.parseObject("{\"resistances\":[\"minecraft:magic\"],\"metadata\":{\"team\":\"fire\"}}")));var ctx=context(core);
        h.runAtTickTime(4,()->{float before=b.getHealth();h.assertTrue(ctx.body.ref().uuid().equals(b.getUUID().toString())&&ctx.body.pos().x==b.getX()&&ctx.body.isAlive(),"Body reference/position/life queries must work");h.assertTrue(b.hurt(h.getLevel().damageSources().magic(),10),"Hit must be accepted");h.assertTrue(Math.abs(before-b.getHealth()-1)<.01,"Selected resistance must reduce damage by 90%");h.assertTrue(ctx.body.health()==b.getHealth(),"Health must be live");var record=core.lastBodyDamage().getAsJsonObject();h.assertTrue(record.get("amount").getAsFloat()==1&&record.get("attacker_type").getAsString().equals("environment"),"Adjusted environment damage must be recorded");var copy=BodyContent.BODY.get().create(h.getLevel());copy.readAdditionalSaveData(b.saveWithoutId(new net.minecraft.nbt.CompoundTag()));h.assertTrue(copy.spec().equals(b.spec())&&copy.lastDamage().json().equals(b.lastDamage().json()),"Recipe and damage record must survive entity NBT");});
        h.runAtTickTime(27,()->{var attacker=EntityType.ZOMBIE.create(h.getLevel());attacker.moveTo(b.position());h.getLevel().addFreshEntity(attacker);h.assertTrue(b.hurt(h.getLevel().damageSources().mobAttack(attacker),100),"Unresisted lethal hit must be accepted");h.assertTrue(!b.isAlive(),"Body must die");b.discard();var record=core.lastBodyDamage().getAsJsonObject();h.assertTrue(record.get("lethal").getAsBoolean()&&record.get("attacker_id").getAsString().equals(attacker.getUUID().toString()),"Mind must retain killer after body removal");h.assertTrue(ctx.body.ref()==null&&ctx.body.health()==0&&!ctx.body.isAlive(),"Missing body handles must be null-safe");var restored=new MindCoreEntity(core.getBlockPos(),core.getBlockState());restored.loadWithComponents(core.saveWithoutMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(restored.lastBodyDamage().equals(record),"Mind damage history must persist");h.succeed();});
    }
    @GameTest(template="empty",timeoutTicks=30) public static void radarUsesRemoteCenterSortedSphericalFilterWithoutChunkLoads(GameTestHelper h){
        var core=core(h);var ctx=context(core);var center=core.getBlockPos().getCenter().add(0,90,0);var near=EntityType.ZOMBIE.create(h.getLevel());near.setNoAi(true);near.moveTo(center.x+1,center.y,center.z);h.getLevel().addFreshEntity(near);var far=EntityType.ZOMBIE.create(h.getLevel());far.setNoAi(true);far.moveTo(center.x+7,center.y,center.z);h.getLevel().addFreshEntity(far);var passive=EntityType.COW.create(h.getLevel());passive.setNoAi(true);passive.moveTo(center.x+2,center.y,center.z);h.getLevel().addFreshEntity(passive);
        var result=dev.jevmod.core.script.ScriptHost.toJson(ctx.entities.scan(center.x,center.y,center.z,10,"hostile")).getAsJsonArray();h.assertTrue(result.size()==2&&result.get(0).getAsJsonObject().get("id").getAsString().equals(near.getUUID().toString()),"Remote radar must find/sort hostiles beyond core nearby range");h.assertTrue(result.get(0).getAsJsonObject().get("hostile").getAsBoolean(),"Radar must include hostile flag");try{ctx.entities.scan(0,0,0,513,"all");h.fail("Oversized scan must fail");}catch(IllegalArgumentException expected){}h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=30) public static void disabledSystemDoesNotInitializeAndDeletedDefaultStaysDeleted(GameTestHelper h){try{
        var core=core(h);String id="qol_disabled_test";JevMod.minds().catalog().systems.put(id,SystemDef.parse(Json.parseObject("{\"enabled\":false,\"script\":\"not_present.js\"}"),id));core.useSystems(List.of(id));
        var root=Files.createTempDirectory(new LocalContent(JevMod.CONTENT_DIR).folder(".history"),"qol-defaults-");dev.jevmod.game.DefaultContent.install(root);var content=new LocalContent(root);content.delete("systems/energy.js");dev.jevmod.game.DefaultContent.install(root);h.assertTrue(!Files.exists(root.resolve("systems/energy.js")),"Explicitly deleted defaults must not respawn");content.save("systems/energy.js","function onTick() {}\n");h.assertTrue(!LocalContent.isDeleted(root,"systems/energy.js"),"Explicit resave must undo deletion marker");
        h.runAtTickTime(6,()->{h.assertTrue(core.error().isEmpty(),"Disabled module must not attempt loading missing script: "+core.error());h.assertTrue(!core.memory().has(id),"Disabled module must not initialize state");JevMod.minds().catalog().systems.remove(id);h.succeed();});
    }catch(Exception e){throw new RuntimeException(e);}}
}
